        RAISE EXCEPTION 'SandIAM 0.8.2 revision043 indexes catalog differs from the exact reviewed structure';
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(captured)), '[]'::jsonb) INTO actual_catalog
    FROM (SELECT c.relname, t.tgname, pg_get_triggerdef(t.oid, true) AS definition
            FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
            JOIN pg_trigger t ON t.tgrelid=c.oid
            WHERE n.nspname='public' AND left(c.relname, char_length('sand_iam')) = 'sand_iam' AND NOT t.tgisinternal
            ORDER BY c.relname,t.tgname) captured;
    IF actual_catalog IS DISTINCT FROM $iam082_triggers$[]$iam082_triggers$::jsonb THEN
        RAISE EXCEPTION 'SandIAM 0.8.2 revision043 triggers catalog differs from the exact reviewed structure';
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(captured)), '[]'::jsonb) INTO actual_catalog
    FROM (SELECT c.relname, p.polname, p.polcmd, p.polpermissive,
            pg_get_expr(p.polqual,p.polrelid) AS using_expression,
            pg_get_expr(p.polwithcheck,p.polrelid) AS check_expression
            FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
            JOIN pg_policy p ON p.polrelid=c.oid
            WHERE n.nspname='public' AND left(c.relname, char_length('sand_iam')) = 'sand_iam' ORDER BY c.relname,p.polname) captured;
    IF actual_catalog IS DISTINCT FROM $iam082_policies$[]$iam082_policies$::jsonb THEN
        RAISE EXCEPTION 'SandIAM 0.8.2 revision043 policies catalog differs from the exact reviewed structure';
    END IF;
END $sand_iam_upgrade_082$;

